9	/**
10	 * Rejects a create request whose normalized telephone is already used by any existing owner.
11	 * Runs after {@code NormalizeOwnerTelephone} so the request telephone is already digits-only;
12	 * each stored telephone is normalized the same way before comparison. Responds 409 on a clash.
13	 */
14	public class RejectDuplicateTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateTelephoneException {
18	        String telephone = request.getTelephone();
19	        for (Owner owner : ownerRepository.findAll()) {
20	            if (telephone.equals(normalize(owner.getTelephone()))) {
21	                throw new DuplicateTelephoneException(telephone);
22	            }
23	        }
24	    }
25	
26	    private String normalize(String telephone) {
27	        return telephone == null ? null : telephone.replaceAll("\\D", "");
28	    }
29	}
